describe('Modal Focus Management - Return to Trigger Button', () => {
  beforeEach(() => {
    cy.visit('/modal-trigger');
  });

  it('should return focus to trigger button when modal closes', () => {
    // Open modal by clicking trigger button
    cy.get('[data-testid="open-modal-btn"]').click();

    // Verify modal is visible
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify focus is on modal trigger button
    cy.get('[data-testid="open-modal-btn"]').should('have.focus');

    // Close modal by clicking close button
    cy.get('[data-testid="close-modal-btn"]').click();

    // Verify modal is no longer visible
    cy.get('[data-testid="modal-dialog"]').should('not.exist');

    // Verify focus has returned to trigger button
    cy.get('[data-testid="open-modal-btn"]').should('have.focus');
  });

  it('should handle focus return when modal closes via escape key', () => {
    // Open modal by clicking trigger button
    cy.get('[data-testid="open-modal-btn"]').click();

    // Verify modal is visible
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify focus is on modal trigger button
    cy.get('[data-testid="open-modal-btn"]').should('have.focus');

    // Close modal by pressing Escape key
    cy.get('body').type('{esc}');

    // Verify modal is no longer visible
    cy.get('[data-testid="modal-dialog"]').should('not.exist');

    // Verify focus has returned to trigger button
    cy.get('[data-testid="open-modal-btn"]').should('have.focus');
  });
});
